import { existsSync } from 'node:fs';
import { defineConfig } from 'prisma/config';

// The CLI (migrate, db pull) always uses the DIRECT connection with the owner
// role (supabase-architecture.md §2, §4). The runtime URL is used by the app.
if (existsSync('.env')) {
  process.loadEnvFile('.env');
}

// DIRECT_DATABASE_URL is the documented name; DIRECT_URL is accepted because
// it is the name commonly generated by the Supabase dashboard.
const migrationUrl = process.env['DIRECT_DATABASE_URL'] ?? process.env['DIRECT_URL'];

export default defineConfig({
  schema: 'prisma/schema',
  migrations: {
    path: 'prisma/migrations',
    seed: 'ts-node --transpile-only prisma/seed/index.ts',
  },
  ...(migrationUrl ? { datasource: { url: migrationUrl } } : {}),
});
